package runner

import (
	"bytes"
	"encoding/json"
	"strings"
)

// Tool titles generated by OpenCode can omit the leading comment character.
// Only display fields are cleaned here; execution arguments, tool IDs and real
// output must retain their original values for precise stopping and inspection.
func cleanOpenCodeToolDisplayText(raw string) string {
	if strings.HasPrefix(strings.TrimLeft(raw, " \t"), "hoxi-stop:") {
		raw = "# " + strings.TrimLeft(raw, " \t")
	}
	return unwrapSandboxCommand(raw)
}

func cleanOpenCodeDisplayFields(fields map[string]interface{}, keys ...string) bool {
	changed := false
	for _, key := range keys {
		if raw, ok := fields[key].(string); ok {
			if cleaned := cleanOpenCodeToolDisplayText(raw); cleaned != raw {
				fields[key] = cleaned
				changed = true
			}
		}
	}
	return changed
}

func openCodeDisplayCommand(input map[string]interface{}) string {
	command := firstString(input["command"], input["cmd"])
	return strings.TrimSpace(strings.SplitN(command, "\n", 2)[0])
}

// stripOpenCodeStopMarker normalizes live managed tool parts before they reach
// Hoxi's store. The sandbox plugin still executes the original tagged command.
func stripOpenCodeStopMarker(part *MessagePart) {
	if part == nil || part.Type != "tool" || part.Tool != "bash" || part.State == nil {
		return
	}
	state := part.State
	cleanOpenCodeDisplayFields(state.Input, "command", "cmd", "description")
	cleanOpenCodeDisplayFields(state.Metadata, "command", "cmd", "description", "title")
	if title := cleanOpenCodeToolDisplayText(state.Title); title != state.Title {
		state.Title = title
		if strings.TrimSpace(title) == "" {
			state.Title = openCodeDisplayCommand(state.Input)
		}
	}
}

// SanitizeOpenCodeToolJSON cleans tool display fields in upstream message
// histories and events, including old persisted Hoxi histories. It deliberately
// preserves user/assistant text, shell output and unrelated metadata, and keeps
// unmodified payloads byte-identical.
func SanitizeOpenCodeToolJSON(raw []byte) []byte {
	if !bytes.Contains(raw, []byte("hoxi-stop:")) && !bytes.Contains(raw, []byte("sandbox-exec")) {
		return raw
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var root interface{}
	if dec.Decode(&root) != nil || !sanitizeOpenCodeToolNode(root) {
		return raw
	}
	if cleaned, err := json.Marshal(root); err == nil {
		return cleaned
	}
	return raw
}

func sanitizeOpenCodeToolNode(node interface{}) bool {
	changed := false
	switch value := node.(type) {
	case []interface{}:
		for _, item := range value {
			changed = sanitizeOpenCodeToolNode(item) || changed
		}
	case map[string]interface{}:
		if value["type"] == "tool" && value["tool"] == "bash" {
			if state, ok := value["state"].(map[string]interface{}); ok {
				input, _ := state["input"].(map[string]interface{})
				meta, _ := state["metadata"].(map[string]interface{})
				changed = cleanOpenCodeDisplayFields(input, "command", "cmd", "description") || changed
				changed = cleanOpenCodeDisplayFields(meta, "command", "cmd", "description", "title") || changed
				if title, ok := state["title"].(string); ok {
					if cleaned := cleanOpenCodeToolDisplayText(title); cleaned != title {
						if strings.TrimSpace(cleaned) == "" {
							cleaned = openCodeDisplayCommand(input)
						}
						state["title"] = cleaned
						changed = true
					}
				}
			}
		}
		// Traverse protocol envelopes only, never arbitrary tool arguments or
		// outputs that may themselves contain JSON or examples of this marker.
		for _, key := range []string{"payload", "properties", "part", "parts"} {
			changed = sanitizeOpenCodeToolNode(value[key]) || changed
		}
	}
	return changed
}

// SanitizeOpenCodeDisplaySSELine covers both global and directory streams. It
// preserves frame boundaries so it can also run on the raw proxy stream.
func SanitizeOpenCodeDisplaySSELine(line string) string {
	if !strings.HasPrefix(line, "data:") || (!strings.Contains(line, "hoxi-stop:") && !strings.Contains(line, "sandbox-exec")) {
		return line
	}
	line = sanitizeOpenCodePermissionSSELine(line)
	trimmed := strings.TrimRight(line, "\r\n")
	payload := []byte(strings.TrimSpace(strings.TrimPrefix(trimmed, "data:")))
	cleaned := SanitizeOpenCodeToolJSON(payload)
	if bytes.Equal(payload, cleaned) {
		return line
	}
	return "data: " + string(cleaned) + line[len(trimmed):]
}
